// Generates readable HTML. JavaScript enhances filtering, practice and persistence.
import fs from 'node:fs';
import vm from 'node:vm';
import {createLearning} from './build-learning.mjs';
const context = {window:{}};
vm.runInNewContext(fs.readFileSync('assets/js/academy-data.js','utf8'), context);
const A = context.window.ACADEMY;
const VERSION = '4.4.2';
const SITE_NAME = 'coachinghub.ro';
const SITE_URL = 'https://coachinghub.ro';
const esc = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const pair = (ro,en) => ({ro,en});
const t = (ro,en,tag='span',attrs='') => `<${tag} data-i18n-ro="${esc(ro)}" data-i18n-en="${esc(en)}"${attrs?' '+attrs:''}>${esc(ro)}</${tag}>`;
const tx = (p,tag='span',attrs='') => t(p.ro,p.en,tag,attrs);
const link = (href,ro,en,cls='ac-link') => `<a class="${cls}" href="${esc(href)}">${t(ro,en)} <span aria-hidden="true">↗</span></a>`;
const label = (ro,en) => t(ro,en,'p','class="ac-eyebrow"');
const kickerEn = s => s.replace('DESCOPERĂ','DISCOVER').replace('COMPETENȚE','COMPETENCIES').replace('ATELIER','STUDIO').replace('ÎN PRACTICĂ','IN PRACTICE').replace('POVEȘTI','STORIES').replace('ÎNTREBĂRI','QUESTIONS').replace('AȘA NU','OOPS').replace('BIBLIOTECĂ','LIBRARY').replace('LECTURI / FUNDAMENTE','READING / FOUNDATIONS').replace('APLICAȚII / INDIVIDUAL','CONTEXTS / INDIVIDUAL').replace('APLICAȚII / ECHIPE','CONTEXTS / TEAMS').replace('CERTIFICARE','CREDENTIALS').replace('ORIENTARE','ORIENTATION');
const head = (kicker,ro,en,leadRo,leadEn) => `<section class="wrap ac-heading">${label(kicker,kickerEn(kicker))}${t(ro,en,'h1')}${t(leadRo,leadEn,'p','class="ac-lead"')}</section>`;
const card = (href,n,ro,en,descRo,descEn) => `<a class="ac-card ac-route" href="${href}">${t(n,n.replace('EXPLORĂ','EXPLORE').replace('APROFUNDEAZĂ','LEARN').replace('CONSTRUIEȘTE','BUILD').replace('LECTURĂ','READ'),'span','class="ac-index"')}${t(ro,en,'h3')}${t(descRo,descEn,'p')}<span class="ac-arrow" aria-hidden="true">↗</span></a>`;
const source = (url,ro='Deschide sursa oficială',en='Open the official source') => link(url,ro,en);
const credentialUpdate = `<aside class="ac-note ac-update-note" role="note"><strong>${t('Actualizare ICF pentru 2027','ICF update for 2027')}</strong>${t('Până la 31 martie 2027 rămân cerințele actuale. Pentru aplicațiile ACC/PCC pe Portfolio depuse de la 1 aprilie 2027, evaluarea de performanță va fi înlocuită de mentor coaching extins cu un mentor care are MCS. Pentru MCC, evaluarea rămâne; din 1 ianuarie 2027 orele noi de mentor coaching trebuie făcute cu un mentor care are MCS. Verifică actualizările ICF înainte să aplici.','Current requirements remain in effect until March 31, 2027. For ACC/PCC Portfolio applications submitted from April 1, 2027, the performance evaluation will be replaced by enhanced mentor coaching with an MCS mentor. For MCC, the performance evaluation remains; from January 1, 2027 new mentor coaching hours must be completed with an MCS mentor. Check ICF updates before applying.','p')}${source('https://coachingfederation.org/blog/mentor-coaching-requirement-replacing-acc-pcc-performance-evaluations/','Verifică anunțul oficial ICF','Check the official ICF update')}</aside>`;
const section = (id,ro,en,body,cls='') => `<section id="${id}" class="ac-section ${cls}">${t(ro,en,'h2')}${body}${id==='credentials'?credentialUpdate:''}</section>`;
const note = (ro,en) => t(ro,en,'p','class="ac-note"');
const footer = `<footer class="site-footer"><div class="wrap ac-footer"><div><a class="ac-footer-brand" href="index.html"><span class="ac-footer-mark"><img src="assets/img/coachinghub-mark.svg?v=${VERSION}" width="36" height="36" alt="" aria-hidden="true"></span><span>coaching<span>hub.ro</span></span></a>${t('Din pasiune pentru profesionalism.','A passion for professionalism.','p')}${t('Învață. Exersează. Conectează-te.','Learn. Practise. Connect.','p')}</div><nav aria-label="Subsol"><a href="hub.html">${t('Paths și roadmap','Paths and roadmap')}</a><a href="forum.html">${t('Blog','Blog')}</a><a href="certificari.html">${t('Credențiale','Credentials')}</a><a href="resurse.html">${t('Bibliotecă','Library')}</a><a href="legal.html">${t('Termeni și confidențialitate','Terms and privacy')}</a><a href="legal.html#corectii">${t('Raportează o corecție','Report a correction')}</a></nav>${note('Proiect educativ independent · RO / EN · Fără afiliere ICF sau EMCC. Exercițiile nu acordă o calificare.','Independent educational project · RO / EN · No ICF or EMCC affiliation. Exercises do not award a qualification.')}</div></footer>`;
const nav = `<header class="site-header"><div class="wrap nav"><a class="logo ac-logo" href="index.html" aria-label="coachinghub.ro — acasă"><span class="ac-logo-mark"><img src="assets/img/coachinghub-mark.svg?v=${VERSION}" width="52" height="52" alt="" aria-hidden="true"></span><span class="logo-text"><b>coaching<span class="ac-brand-tail">hub.ro</span></b></span></a><nav class="navlinks" id="navlinks" aria-label="Navigare principală"><a href="descopera.html">Explorează</a><a href="hub.html">Paths</a><a href="invata.html">Practică</a><a href="https://puzzletogether-kx1v.onrender.com/?lang=ro">Ateliere</a><a href="forum.html">Blog</a><a href="resurse.html">Bibliotecă</a></nav><div class="nav-actions"><button class="icon-btn" id="themeBtn" aria-label="Comută tema"><svg id="themeIcon" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M21 12.8A9 9 0 1111.2 3a7 7 0 009.8 9.8z"/></svg></button><button class="lang-btn" id="langBtn" aria-label="Schimbă limba"><span id="langLabel">EN</span></button><button class="icon-btn nav-toggle" id="navToggle" aria-label="Meniu" aria-expanded="false"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 7h16M4 12h16M4 17h16"/></svg></button></div></div></header>`;
function page(file,id,title,main,desc='Învață coaching prin explicații clare, exemple și exerciții. Explorează competențele ICF și construiește o practică responsabilă.') {
  const canonical = SITE_URL+'/'+(file==='index.html'?'':file);
  const learningAssets = ['descopera','competente','modele','dovezi','theory'].includes(id)||id.startsWith('competenta-');
  const extraHead = learningAssets ? `<link rel="stylesheet" href="assets/css/learning.css?v=${VERSION}">` : '';
  const extraScript = learningAssets ? `<script src="assets/js/learning.js?v=${VERSION}"></script>` : '';
  const schema = id === 'index' ? {
    '@context':'https://schema.org',
    '@graph':[
      {'@type':'WebSite','@id':SITE_URL+'/#website','url':SITE_URL+'/',name:SITE_NAME,description:desc,inLanguage:['ro','en']},
      {'@type':'EducationalOrganization','@id':SITE_URL+'/#organization','url':SITE_URL+'/',name:SITE_NAME,description:'Hub educațional independent pentru coaching, practică și dezvoltare profesională.'}
    ]
  } : id === 'theory' ? {
    '@context':'https://schema.org',
    '@type':'Article',
    headline:title.ro,
    description:desc,
    url:canonical,
    inLanguage:'ro',
    publisher:{'@type':'Organization',name:SITE_NAME,url:SITE_URL+'/'},
    isPartOf:{'@id':SITE_URL+'/#website'}
  } : null;
  const structured = schema ? `<script type="application/ld+json">${JSON.stringify(schema).replace(/</g,'\\u003c')}</script>` : '';
  fs.writeFileSync(file,`<!DOCTYPE html>
<html lang="ro" data-title-ro="${esc(title.ro)} — ${SITE_NAME}" data-title-en="${esc(title.en)} — ${SITE_NAME}"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"><title>${esc(title.ro)} — ${SITE_NAME}</title><meta name="description" content="${esc(desc)}" data-desc-ro="${esc(desc)}" data-desc-en="Learn coaching through clear explanations, examples and practice. Explore the ICF competencies and develop responsible practice."><meta name="theme-color" content="#1f4c3e"><meta name="color-scheme" content="light dark"><link rel="canonical" href="${canonical}"><meta property="og:type" content="website"><meta property="og:title" content="${esc(title.ro)} — ${SITE_NAME}"><meta property="og:description" content="${esc(desc)}"><meta property="og:url" content="${canonical}"><meta property="og:image" content="${SITE_URL}/assets/img/academy-conversation.webp?v=${VERSION}"><link rel="icon" href="assets/img/favicon.svg?v=${VERSION}"><link rel="preload" href="assets/fonts/inter-latin-ext-wght-normal.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="assets/css/fonts.css?v=${VERSION}"><link rel="stylesheet" href="assets/css/tokens.css?v=${VERSION}"><link rel="stylesheet" href="assets/css/app.css?v=${VERSION}"><link rel="stylesheet" href="assets/css/atlas.css?v=${VERSION}"><link rel="stylesheet" href="assets/css/academy.css?v=${VERSION}"><link rel="stylesheet" href="assets/css/old-money.css?v=${VERSION}">${extraHead}${structured}<script>try{document.documentElement.dataset.theme=localStorage.getItem('cp_theme')||'dark'}catch(e){document.documentElement.dataset.theme='dark'}document.documentElement.classList.add('js')</script></head><body class="academy" data-page="${id}" data-app="lite"><a class="skip-link" href="#main">${t('Sari la conținut','Skip to content')}</a><div class="read-progress" aria-hidden="true"></div>${nav}<main id="main">${main}</main>${footer}<div class="toast" id="toast" role="status" aria-live="polite"></div><button class="to-top" id="toTop" aria-label="Înapoi sus">↑</button><script src="assets/js/site.js?v=${VERSION}"></script><script src="assets/js/academy-data.js?v=${VERSION}"></script><script src="assets/js/academy.js?v=${VERSION}"></script>${extraScript}</body></html>\n`);
}
const learning = createLearning({page,t,tx,link,label,head,note,section,esc,A,VERSION});
const routes = `<div class="ac-home-search"><label for="acHomeSearch">${t('Cauți ceva anume?','Looking for something specific?')}</label><input id="acHomeSearch" type="search" placeholder="Etică, ascultă, ICF…" data-i18n-ph-ro="Etică, ascultă, ICF…" data-i18n-ph-en="Ethics, listen, ICF…" aria-describedby="acHomeSearchStatus"><p id="acHomeSearchStatus" role="status" class="ac-note"></p><ul id="acHomeResults" hidden></ul></div><div class="ac-grid ac-grid-3">${card('descopera.html','01 / EXPLORĂ','Nu știu nimic. De aici încep.','I am new. Start here.','Ce este coachingul, unde ajută și cum arată o conversație.','What coaching is, where it helps and what a conversation looks like.')}${card('competente.html','02 / APROFUNDEAZĂ','Vreau să devin un coach bun.','I want to become a good coach.','Opt competențe, exemple reale ca situație și exerciții de încercat.','Eight competencies, realistic examples and exercises to try.')}${card('certificari.html','03 / CONSTRUIEȘTE','Îmi caut drumul profesional.','I am finding my professional path.','Înțelege certificările și întrebările potrivite pentru o școală.','Understand credentials and what to ask a training provider.')}</div>`;
page('index.html','index',pair('Conversații care deschid posibilități','Conversations that open possibilities'),`<section class="wrap ac-hero"><div class="ac-hero-copy">${label('UN SPAȚIU PENTRU OAMENI CURIOȘI','A SPACE FOR CURIOUS PEOPLE')}<h1>${t('O conversație bună','A good conversation')} <em>${t('schimbă perspectiva.','changes perspective.')}</em></h1>${t('Învață arta și responsabilitatea coachingului. De la primul „ce este?” la practica de zi cu zi, o descoperire pe rând.','Learn the art and responsibility of coaching. From your first “what is it?” to everyday practice, one discovery at a time.','p','class="ac-lead"')}<div class="ac-actions">${link('descopera.html','Începe explorarea','Start exploring','ac-btn ac-btn-primary')}${link('invata.html','Intră în atelier','Enter the practice studio')}</div>${note('Gratuit. Fără cont. În ritmul tău.','Free. No account. At your pace.')}</div><figure class="ac-hero-art"><img src="assets/img/academy-conversation.webp?v=3.0.0" alt="Două persoane într-o conversație atentă, cu un drum care se deschide în fundal" width="1536" height="1024" fetchpriority="high"><figcaption>${t('Ascultă. Explorează. Lasă loc descoperirii.','Listen. Explore. Leave room for discovery.')}</figcaption><div class="ac-art-stamp" aria-hidden="true">mai multă<br><i>curiozitate.</i></div></figure></section><div class="wrap">${section('alege','Ești nou în coaching?','New to coaching?',routes)}<section class="ac-home-progress" id="acHomeProgress" hidden></section><section class="ac-feature"><div>${label('ÎNVAȚĂ PRIN EXPERIENȚĂ','LEARN THROUGH EXPERIENCE')}${t('Tu ce ai spune mai departe?','What would you say next?','h2')}${t('Ana vrea să renunțe la job. Îți cere un sfat. Alege o replică și descoperă ce poate deschide sau închide într-o conversație.','Ana wants to leave her job. She asks for a response. Choose a reply and explore what it might open up or close down in a conversation.','p')}${link('povesti.html#cariera','Intră în poveste','Enter the story','ac-btn')}</div><div class="ac-chat-preview"><span class="ac-avatar" aria-hidden="true">A</span><blockquote>${t('„Spune-mi tu ce să fac.”','“You tell me what to do.”')}</blockquote><p>${t('Un răspuns rapid sau o întrebare bună?','A quick answer or a thoughtful question?')}</p><span class="ac-chat-dots" aria-hidden="true">● ● ●</span></div></section>${section('azi','O întrebare de luat cu tine.','A question to take with you.',`<div class="ac-daily"><blockquote id="acDailyQuestion">${tx(A.questions[0].text)}</blockquote>${link('intrebari.html','Explorează banca de întrebări','Explore the question bank')}</div>`)}<section class="ac-manifesto">${label('DE CE EXISTĂ ACEST LOC','WHY THIS SPACE EXISTS')}${t('Din pasiune pentru profesionalism.','A passion for professionalism.','h2')}${t('Credem în conversații atente, în surse verificabile și în practica făcută cu grijă. Pentru profesioniștii în coaching și pentru oricine vrea să înțeleagă înainte să aleagă.','We believe in attentive conversations, verifiable sources and thoughtful practice. For coaching professionals and anyone who wants to understand before choosing.','p')}</section></div>`);

const comparisons=[
  ['Coaching','Coaching','Explorezi propriile obiective, opțiuni și alegeri într-un parteneriat.','Explore your own goals, options and choices in a partnership.','„Ce opțiune se potrivește criteriilor tale?”','“Which option fits your criteria?”'],
  ['Mentorat','Mentoring','Înveți și din experiența cuiva într-un domeniu. Rolul de mentor este explicit.','Learn from someone’s experience in a field. The mentoring role is explicit.','„Pot să-ți arăt cum am abordat eu asta.”','“I can show you how I approached this.”'],
  ['Consultanță','Consulting','Ceri expertiză, analiză sau recomandări pentru o problemă.','Seek expertise, analysis or recommendations for a problem.','„Acestea sunt opțiunile pe care le recomand.”','“These are the options I recommend.”'],
  ['Psihoterapie','Psychotherapy','Lucrezi cu un profesionist calificat asupra dificultăților psihologice și a altor obiective terapeutice. Poate include trecutul, prezentul și viitorul.','Work with a qualified professional on psychological difficulties and other therapeutic goals. This may include the past, present and future.','Scopul, pregătirea și cadrul sunt diferite; simpla temă sau emoția nu fac delimitarea.','Purpose, training and framework differ; a topic or emotion alone does not define the boundary.']
];
page('descopera.html','descopera',pair('Ce este, de fapt, coachingul?','What is coaching, really?'),`${head('01 / DESCOPERĂ','Mai întâi, să facem lumină.','First, let’s make it clear.','Nu ai nevoie de jargon. Ai nevoie de o idee clară, de un exemplu și de libertatea de a întreba.','You do not need jargon. You need a clear idea, an example and the freedom to ask.')}<div class="wrap ac-reading"><nav class="ac-jumps" aria-label="În această pagină">${link('#ce-este','Ce este','What it is')}${link('#diferente','Ce alegi','What to choose')}${link('#grow','GROW','GROW')}${link('#modele','Modele','Models')}${link('#companii','Companii și studii','Companies and studies')}${link('#aplicatii','Unde se aplică','Where it applies')}${link('#istorie','De unde vine','Where it comes from')}</nav>${section('ce-este','Coachingul, în 30 de secunde.','Coaching in 30 seconds.',`${t('Este un parteneriat de conversație și reflecție în care o persoană își explorează obiectivele, înțelege mai bine situația și alege pași potriviți pentru ea. Coachul susține procesul; clientul rămâne autorul alegerilor sale.','It is a partnership of conversation and reflection in which a person explores goals, understands their situation and chooses steps that fit. The coach supports the process; the client remains the author of their choices.','p','class="ac-large-text"')}${source('https://coachingfederation.org/get-coaching/coaching-for-me/what-is-coaching/','Aprofundează definiția ICF','Explore the ICF definition')}<div class="ac-callout">${t('Nu ai nevoie să vrei să devii coach pentru ca acest loc să-ți fie util. Poți învăța să alegi un profesionist sau să fii un interlocutor mai atent.','You do not need to want to become a coach for this space to be useful. You can learn to choose a professional or become a more attentive conversation partner.','p')}</div>`)}${learning.conversationMap()}${section('diferente','De ce fel de sprijin ai nevoie?','What kind of support do you need?',`<div class="ac-grid ac-grid-2">${comparisons.map(c=>`<article class="ac-card">${t(c[0],c[1],'h3')}${t(c[2],c[3],'p')}${t(c[4],c[5],'p','class="ac-example"')}</article>`).join('')}</div>${note('Aceste servicii se pot completa. Un profesionist care are mai multe roluri trebuie să clarifice în ce rol lucrează și cu ce acord. Coachingul nu înlocuiește îngrijirea medicală sau psihoterapia.','These services can complement one another. A professional with multiple roles should clarify the role and agreement in use. Coaching does not replace medical care or psychotherapy.')}`)}${section('sesiune','Cum arată o conversație?','What does a conversation look like?',`<ol class="ac-steps"><li>${t('Alegeți o direcție','Choose a direction','h3')}${t('„Cu ce ai vrea să pleci din conversația de azi?”','“What would you like to leave today’s conversation with?”','p')}</li><li>${t('Explorați ce se întâmplă','Explore what is happening','h3')}${t('Observații, context, valori și presupuneri. Nu o anchetă, ci curiozitate în serviciul clientului.','Observations, context, values and assumptions. Curiosity in service of the client.','p')}</li><li>${t('Faceți loc altor posibilități','Make room for possibilities','h3')}${t('Clientul descoperă perspective și alternative. Nu trebuie să existe un moment spectaculos.','The client discovers perspectives and alternatives. A dramatic breakthrough is not required.','p')}</li><li>${t('Încheiați cu o alegere','Close with a choice','h3')}${t('Ce a devenit mai clar? Ce vrea clientul să încerce sau să continue să reflecteze?','What became clearer? What does the client want to try or keep reflecting on?','p')}</li></ol>${link('povesti.html','Încearcă o conversație fictivă','Try a fictional conversation','ac-btn ac-btn-primary')}`)}${learning.discoverSections()}${section('aplicatii','Aceeași atenție. Contexte diferite.','The same attention. Different contexts.',`<div class="ac-grid ac-grid-2">${card('individual.html','01','Viață și carieră','Life and career','Alegeri, tranziții, priorități. Obiectivul aparține clientului.','Choices, transitions and priorities. The goal belongs to the client.')}${card('individual.html#leadership','02','Leadership','Leadership','Delegare, relații profesionale, decizii. Clarifică și rolul sponsorului.','Delegation, working relationships and decisions. Clarify the sponsor’s role, too.')}${card('echipa.html','03','Echipe','Teams','Un scop comun și felul în care echipa interacționează pentru a-l atinge.','A shared purpose and how the team interacts to reach it.')}${card('intrebari.html','04','Conversații cotidiene','Everyday conversations','Poți asculta mai bine fără să transformi orice relație într-o sesiune.','You can listen better without turning every relationship into a session.')}</div>`)}${section('istorie','Un domeniu cu mai multe rădăcini.','A field with several roots.',`${t('Coachingul modern aduce împreună influențe din sport, învățarea adulților, leadership și abordări ale dezvoltării umane. Nu are o singură poveste de origine. Câteva repere ajută orientarea:','Modern coaching brings together influences from sport, adult learning, leadership and approaches to human development. It has no single origin story. A few milestones help with orientation:','p')}<div class="ac-timeline"><div><b>1992</b>${t('Coaching for Performance contribuie la răspândirea GROW în organizații.','Coaching for Performance helps spread GROW in organisations.','p')}${source(A.resources.find(r=>r.id==='performance').url,'Cartea și istoria ei','The book and its history')}</div><div><b>1995</b>${t('Ia naștere International Coaching Federation.','The International Coaching Federation is founded.','p')}${source('https://coachingfederation.org/about/history/','Istoria ICF','ICF history')}</div><div><b>2025</b>${t('ICF actualizează cadrul competențelor și codul etic. Standardele evoluează odată cu profesia.','ICF updates its competency framework and ethics code. Standards evolve with the profession.','p')}${source(A.core)}</div></div>`)}${section('continua','Ai bazele. Acum vezi-le în acțiune.','You have the basics. Now see them in action.',`${link('competente.html','Explorează cele 8 competențe','Explore the 8 competencies','ac-btn ac-btn-primary')} ${link('incepe.html','Urmează traseul ghidat în 10 pași','Follow the guided 10-step journey')}`)}</div>`);

learning.build();

page('invata.html','invata',pair('Atelierul tău de practică','Your practice studio'),`${head('03 / ATELIER','Mai puțin „știu”. Mai mult „încerc”.','Less “I know”. More “I try”.','Alege o competență. Exersează cu un partener care își dă acordul. Păstrează o observație pentru data viitoare.','Choose a competency. Practise with a consenting partner. Keep an observation for next time.')}<div class="wrap"><div class="ac-studio"><div class="ac-studio-side">${label('O PRACTICĂ MICĂ. ATENȚIE MARE.','SMALL PRACTICE. FULL ATTENTION.')}${t('Cu ce vrei să lucrezi?','What would you like to work on?','label','for="acPracticeSelect"')}<select id="acPracticeSelect">${A.competencies.map((c,i)=>`<option value="${c.id}" data-i18n-ro="${i+1}. ${esc(c.name.ro)}" data-i18n-en="${i+1}. ${esc(c.name.en)}">${i+1}. ${esc(c.name.ro)}</option>`).join('')}</select><p id="acPracticeProgress" role="status"></p><progress id="acProgress" max="8" value="0" aria-label="Competențe exersate"></progress>${note('Marchezi exerciții încercate, nu competențe certificate. Ritmul îl alegi tu.','You mark exercises you tried, not certified competencies. You choose the pace.')}${link('competente.html','Recitește explicațiile','Revisit the explanations')}<div class="ac-studio-drawing" aria-hidden="true"><span></span><i></i><b>∞</b></div></div><div class="ac-studio-main"><div id="acPracticeContent">${tx(A.competencies[0].name,'h2')}${tx(A.competencies[0].practice,'p')}</div><label for="acReflection" id="acReflectionLabel">${t('Ce ai observat?','What did you notice?')}</label><textarea id="acReflection" rows="5" maxlength="4000" aria-describedby="acNotesPrivacy" data-i18n-ph-ro="O observație despre propria practică. Fără nume sau detalii identificabile despre alte persoane." data-i18n-ph-en="An observation about your own practice. No names or identifying details about other people." placeholder="O observație despre propria practică. Fără nume sau detalii identificabile despre alte persoane."></textarea>${t('Notițele se salvează doar când apeși butonul, în acest browser. Oricine folosește profilul browserului le poate vedea. Poți exporta sau șterge jurnalul mai jos.','Notes are saved only when you press the button, in this browser. Anyone using this browser profile can see them. You can export or delete the journal below.','p','id="acNotesPrivacy" class="ac-note"')}<div class="ac-actions"><button class="ac-btn ac-btn-primary" id="acSaveNote">${t('Salvează reflecția','Save reflection')}</button><button class="ac-btn" id="acMarkDone" aria-pressed="false">${t('Am încercat exercițiul','I tried the exercise')}</button></div><p id="acSaveStatus" role="status" aria-live="polite"></p></div></div>${section('jurnal','Jurnalul tău de învățare.','Your learning journal.',`<div id="acJournal"></div><div class="ac-actions"><button class="ac-btn" id="acExport">${t('Descarcă jurnalul (.txt)','Download journal (.txt)')}</button><button class="ac-text-button" id="acReset">${t('Șterge jurnalul și progresul atelierului','Delete studio journal and progress')}</button></div>${note('Datele nu se sincronizează între dispozitive. Exportă ce vrei să păstrezi; curățarea browserului poate șterge progresul.','Data does not sync across devices. Export what you want to keep; clearing the browser can erase progress.')}`)}${section('alte-experimente','Schimbă felul în care exersezi.','Try a different way to practise.',`<div class="ac-grid ac-grid-3">${card('povesti.html','01','Alege replica','Choose the response','Patru situații fictive. Explorează consecințele fiecărei alegeri.','Four fictional situations. Explore the consequences of each choice.')}${card('intrebari.html','02','Laboratorul de întrebări','The question lab','Caută, salvează și reformulează întrebări cu intenție.','Search, save and rephrase questions with intention.')}${card('greseli.html','03','Așa nu. Și apoi?','Oops. What next?','Greșeli de practică, reparații posibile și semnale de alarmă.','Practice mistakes, possible repairs and warning signs.')}</div>`)}<noscript>${note('Activează JavaScript pentru jurnal. Poți citi toate exercițiile în pagina Competențe.','Enable JavaScript for the journal. All exercises are readable on the Competencies page.')}</noscript></div>`);

page('povesti.html','povesti',pair('Povești în care alegi replica','Stories where you choose the response'),`${head('ÎN PRACTICĂ / POVEȘTI','O situație. Mai multe posibilități.','One situation. Several possibilities.','Deschide o replică și vezi ce poate produce. Explorează-le pe toate: învățarea stă în diferențe, nu într-un scor.','Open a response and see what it might produce. Explore them all: learning is in the differences, not a score.')}<div class="wrap ac-reading">${note('Personaje și dialoguri fictive, scrise pentru învățare. Feedbackul ilustrează posibilități; nu prezice reacțiile unei persoane reale.','Fictional characters and dialogues written for learning. Feedback illustrates possibilities; it does not predict a real person’s reactions.')}<nav class="ac-jumps" aria-label="Povești">${A.stories.map(s=>link('#'+s.id,s.title.ro,s.title.en)).join('')}</nav>${A.stories.map((s,i)=>`<article class="ac-story ac-section" id="${s.id}">${tx(s.context,'p','class="ac-eyebrow"')}${tx(s.title,'h2')}<div class="ac-story-scene"><span class="ac-avatar" aria-hidden="true">${['A','E','M','R'][i]}</span>${tx(s.situation,'p')}</div>${t('Cum ai răspunde? Deschide o variantă.','How would you respond? Open an option.','h3')}<div class="ac-story-options">${s.options.map((o,j)=>`<details class="ac-choice"><summary><span class="ac-choice-letter" aria-hidden="true">${String.fromCharCode(65+j)}</span>${tx(o.text)}</summary><div class="ac-choice-feedback">${t(o.preferred?'O invitație de explorat':'Ce merită observat',o.preferred?'An invitation to explore':'What to notice','strong')}${tx(o.feedback,'p')}</div></details>`).join('')}</div><div class="ac-takeaway">${tx(s.takeaway,'p')}${link('competente.html#'+s.competency,'Vezi competența din spatele conversației','Explore the competency behind the conversation')}</div></article>`).join('')}</div>`);

const qTypes={all:pair('Toate tipurile','All types'),clarify:pair('Clarificare','Clarifying'),explore:pair('Explorare','Exploring'),action:pair('Acțiune','Action'),reflect:pair('Reflecție','Reflecting')};
function options(values){return Object.entries(values).map(([v,p])=>`<option value="${v}" data-i18n-ro="${esc(p.ro)}" data-i18n-en="${esc(p.en)}">${esc(p.ro)}</option>`).join('');}
function filters(prefix,types,placeholder){return `<div class="ac-filterbar"><div><label for="${prefix}Search">${t('Caută','Search')}</label><input type="search" id="${prefix}Search" placeholder="${esc(placeholder)}" data-i18n-ph-ro="${esc(placeholder)}" data-i18n-ph-en="Search by word or topic"></div><div><label for="${prefix}Type">${t('Categorie','Category')}</label><select id="${prefix}Type">${options(types)}</select></div><label class="ac-check"><input type="checkbox" id="${prefix}Saved">${t('Doar salvate','Saved only')}</label><button class="ac-text-button" id="${prefix}Reset">${t('Resetează filtrele','Reset filters')}</button></div><p id="${prefix}Count" class="ac-note" role="status" aria-live="polite"></p>`;}
page('intrebari.html','intrebari',pair('Laboratorul de întrebări','The question lab'),`${head('ÎN PRACTICĂ / ÎNTREBĂRI','Curiozitate cu intenție.','Curiosity with intention.','O întrebare bună vine din ascultare. Folosește aceste repere ca inspirație, nu ca listă de bifat într-o sesiune.','A good question comes from listening. Use these prompts as inspiration, not as a session checklist.')}<div class="wrap">${filters('acQ',qTypes,'Ex.: context, alegere, sprijin…')}<div class="ac-grid ac-grid-3" id="acQuestions">${A.questions.map(q=>`<article class="ac-question ac-card" data-question="${q.id}" data-type="${q.type}">${tx(qTypes[q.type],'p','class="ac-eyebrow"')}${tx(q.text,'h2')}${tx(q.purpose,'p')}<button class="ac-save" data-save-question="${q.id}" aria-pressed="false">${t('Salvează întrebarea','Save question')}</button></article>`).join('')}</div><p class="ac-empty" id="acQEmpty" hidden>${t('Nicio întrebare în această selecție. Încearcă alt cuvânt sau resetează filtrele.','No questions in this selection. Try another word or reset the filters.')}</p>${section('reformulare','Din sfat mascat în invitație.','From disguised advice to invitation.',`<div class="ac-lab"><div>${t('„Nu crezi că ar trebui să delegi?”','“Don’t you think you should delegate?”','blockquote')}${t('O asemenea formulare împinge spre o soluție. Încearcă să lași deschise și alte opțiuni.','This wording pushes towards a solution. Try leaving other options open.','p')}</div><div><label for="acRewrite">${t('Cum ai reformula tu?','How would you rephrase it?')}</label><textarea id="acRewrite" rows="3" maxlength="1000"></textarea><button class="ac-btn" id="acShowRewrite" aria-expanded="false" aria-controls="acRewriteGuide">${t('Compară cu reperele','Compare with the guide')}</button><div id="acRewriteGuide" hidden><p>${t('Verifică: este scurtă? Lasă răspunsul deschis? Folosește limbajul clientului? Include o singură întrebare?','Check: is it short? Does it leave the answer open? Does it use the client’s language? Is it one question?')}</p><ul><li>${t('„Ce opțiuni vezi pentru volumul acesta de lucru?”','“What options do you see for this workload?”')}</li><li>${t('„Ce te-ar ajuta să alegi ce păstrezi la tine?”','“What would help you decide what to keep doing yourself?”')}</li></ul>${note('Exemple de comparat, nu o evaluare automată. Textul tău nu este trimis sau salvat.','Examples for comparison, not an automated assessment. Your text is neither sent nor saved.')}</div></div></div>`)}</div>`);

page('greseli.html','greseli',pair('Greșeli de practică și semnale de alarmă','Practice mistakes and warning signs'),`${head('ÎN PRACTICĂ / AȘA NU','Coachul nu are nevoie de o pelerină.','A coach does not need a cape.','Unele greșeli cer practică și feedback. Alte comportamente cer limite clare. Învață să faci diferența.','Some mistakes call for practice and feedback. Other behaviours call for firm boundaries. Learn to tell the difference.')}<div class="wrap"><div class="ac-filterbar"><label for="acMistakeType">${t('Ce vrei să explorezi?','What would you like to explore?')}</label><select id="acMistakeType">${options({all:pair('Toate cele 12 situații','All 12 situations'),practice:pair('Greșeli frecvente la început','Common beginner mistakes'),red:pair('Semnale de alarmă','Warning signs')})}</select><span role="status" id="acMistakeCount"></span></div><div class="ac-grid ac-grid-2">${A.mistakes.map(m=>`<details class="ac-mistake ac-card" data-severity="${m.severity}"><summary><span class="ac-tag ${m.severity==='red'?'ac-tag-red':''}">${t(m.severity==='red'?'Semnal de alarmă':'De exersat',m.severity==='red'?'Warning sign':'Practice opportunity')}</span>${tx(m.title,'h2')}${tx(m.signal,'p')}</summary><div class="ac-repair">${t(m.severity==='red'?'Ce poți face':'Cum repari direcția',m.severity==='red'?'What you can do':'How to adjust your approach','h3')}${tx(m.repair,'p')}</div></details>`).join('')}</div>${section('alegere','Ai voie să întrebi. Ai voie să spui nu.','You can ask. You can say no.',`${t('Înainte să începi, cere explicații despre pregătire, cadrul de lucru, confidențialitate și posibilitatea de a încheia colaborarea. Poți verifica acreditarea declarată și poți cere timp pentru a decide. Un titlu singur nu garantează potrivirea.','Before you start, ask about training, the working agreement, confidentiality and ending the engagement. You can verify a claimed credential and take time to decide. A title alone does not guarantee a good fit.','p')}${source(A.ethics,'Consultă codul etic ICF','Read the ICF ethics code')}${link('certificari.html','Înțelege certificările','Understand credentials')}`)}</div>`);

const resTypes={all:pair('Toate resursele','All resources'),official:pair('Documentație oficială','Official documents'),books:pair('Cărți','Books'),articles:pair('Bloguri și articole','Blogs and articles'),research:pair('Cercetare','Research')};
page('resurse.html','resurse',pair('Biblioteca de coaching','The coaching library'),`${head('05 / BIBLIOTECĂ','Mai multă profunzime. Mai puțin zgomot.','More depth. Less noise.','Documente, cărți și idei de explorat. Fiecare resursă are un rol: standard, perspectivă de autor sau cercetare.','Documents, books and ideas to explore. Each resource has a role: a standard, an author’s perspective or research.')}<div class="wrap"><div class="ac-library-banner"><img src="assets/img/academy-library.webp?v=3.0.0" width="1536" height="1024" loading="lazy" alt="Cărți și un caiet deschis pe o masă luminoasă"><div>${label('CITEȘTE. ÎNCEARCĂ. REVINO.','READ. TRY. RETURN.')}${t('O idee devine valoroasă când o examinezi.','An idea becomes valuable when you examine it.','h2')}${t('Alege o lectură, notează o întrebare și observă ce schimbă în practica ta.','Choose a reading, note a question and notice what it changes in your practice.','p')}</div></div>${filters('acR',resTypes,'Ex.: ICF, etică, GROW…')}<div class="ac-grid ac-grid-3" id="acResources">${A.resources.map((r,i)=>`<article class="ac-resource ac-card" data-resource="${r.id}" data-type="${r.type}"><div class="ac-resource-symbol" aria-hidden="true">${r.type==='books'?'Aa':r.type==='official'?'§':r.type==='research'?'↗':'…'}</div>${tx(resTypes[r.type],'p','class="ac-eyebrow"')}<h2>${esc(r.title)}</h2>${tx(r.description,'p')}<div class="ac-card-actions">${link(r.url,'Deschide resursa','Open resource')}<button class="ac-save" data-save-resource="${r.id}" aria-pressed="false">${t('Salvează','Save')}</button></div></article>`).join('')}</div><p id="acREmpty" class="ac-empty" hidden>${t('Nicio resursă în această selecție. Încearcă alt filtru.','No resources in this selection. Try another filter.')}</p>${note('Linkuri către editori și organizații, fără afiliere comercială. Cărțile pot necesita cumpărare; nu găzduim copii ale lor. Sursele de mai sus au fost consultate la 16 septembrie 2026.','Links to publishers and organisations, with no commercial affiliation. Books may require purchase; we do not host copies. The sources above were consulted on September 16, 2026.')}${section('lecturi','De citit aici, pe îndelete.','Read here, at your pace.',`<div class="ac-grid ac-grid-2">${card('teorie.html#grow','LECTURĂ / 3 MIN','GROW fără pilot automat','GROW without autopilot','Un model util, dacă nu-l confunzi cu conversația.','A useful model, when you do not confuse it with the conversation.')}${card('individual.html#prima','LECTURĂ / 3 MIN','Prima întâlnire, înainte de prima întrebare','The first meeting, before the first question','Acorduri, așteptări și dreptul de a alege.','Agreements, expectations and the right to choose.')}${card('echipa.html#sponsor','LECTURĂ / 3 MIN','Cine este clientul când plătește organizația?','Who is the client when the organisation pays?','Trei perspective de adus într-un acord comun.','Three perspectives to bring into a shared agreement.')}${card('teorie.html#reflectie','LECTURĂ / 3 MIN','Cum înveți dintr-o conversație','How to learn from a conversation','Diferența dintre „a mers bine” și observații folositoare.','The difference between “it went well” and useful observations.')}</div>`)}</div>`);

const article = (id,ro,en,paras) => section(id,ro,en,paras.map(p=>t(p[0],p[1],'p')).join(''));
page('teorie.html','theory',pair('Idei care susțin practica','Ideas that support practice'),`${head('LECTURI / FUNDAMENTE','Înțelege înainte să aplici.','Understand before applying.','Trei lecturi scurte pentru o practică atentă. Modelele ajută orientarea; conversația rămâne vie.','Three short readings for thoughtful practice. Models offer orientation; the conversation remains alive.')}<div class="wrap ac-reading ac-prose">${section('aprofundare','Explorează modelele în detaliu','Explore the models in depth',learning.modelCards())}${article('grow','GROW fără pilot automat','GROW without autopilot',[
['GROW este un reper pentru explorarea unui obiectiv (Goal), a situației prezente (Reality), a opțiunilor (Options) și a alegerii unui pas (Will / Way forward). Îl poți folosi ca hartă a conversației, fără să impui clientului un traseu rigid.','GROW is a guide for exploring a goal, current reality, options and a way forward. Use it as a conversation map without imposing a rigid route on the client.'],
['Imaginează-ți că Ioana vrea să delege mai mult. Înainte să generați opțiuni, verifici ce vrea să obțină din sesiune. „Să deleg” poate fi o soluție deja aleasă, în timp ce nevoia este să înțeleagă de ce îi este greu să ceară sprijin.','Imagine Ioana wants to delegate more. Before generating options, check what she wants from the session. “To delegate” may be a preselected solution, while her need is to understand why asking for support feels difficult.'],
['În explorare, distinge observațiile de presupuneri. „Echipa nu poate” este o afirmație de verificat, nu un fapt de adoptat. Întreabă ce a observat concret și ce experiențe sau resurse ar putea completa perspectiva.','During exploration, distinguish observations from assumptions. “The team cannot do it” is a claim to examine, not a fact to adopt. Ask what she actually observed and what experiences or resources might add perspective.'],
['La încheiere, clientul poate alege un experiment sau poate avea nevoie să reflecteze. Un plan lung nu este dovada unei sesiuni bune. Întreabă ce a devenit mai clar și ce pas își asumă persoana în contextul ei.','At the end, the client may choose an experiment or need time to reflect. A long plan does not prove that a session was useful. Ask what became clearer and what step the person owns in their context.']
])}${source(A.resources.find(r=>r.id==='performance').url,'Lectură asociată: Coaching for Performance','Related reading: Coaching for Performance')}${article('etica','Etica se vede în alegeri mici','Ethics shows up in small choices',[
['Un acord clar nu este doar un document semnat. Este o înțelegere pe care o puteți explica: ce faceți împreună, cine decide, cum folosiți informațiile și cum încheiați colaborarea. Revino la el când apare o schimbare.','A clear agreement is more than a signed document. It is an understanding you can explain: what you do together, who decides, how information is used and how the engagement ends. Revisit it when something changes.'],
['Un sponsor poate dori rezultate observabile, iar clientul poate avea nevoie de un spațiu de explorare. Clarificați de la început ce se raportează și cui. Faptul că cineva plătește nu îi oferă automat acces la conținutul sesiunilor.','A sponsor may want observable results while the client needs space to explore. Clarify what is reported and to whom from the start. Paying does not automatically provide access to session content.'],
['Observă și puterea din relație. Clientul poate accepta o idee doar ca să nu te dezamăgească. Invită dezacordul și cere feedback fără să-l transformi într-o probă de loialitate.','Notice power in the relationship, too. A client may accept an idea to avoid disappointing you. Invite disagreement and ask for feedback without making it a loyalty test.'],
['O dilemă nu dispare dacă alegi o tehnică mai bună. Verifică standardele aplicabile, consultă un supervizor sau o resursă etică potrivită și protejează informațiile persoanelor implicate. ICF are propriul cod; Global Code of Ethics este un cadru separat, susținut de EMCC și alți semnatari.','A dilemma does not disappear when you choose a better technique. Check applicable standards, consult a supervisor or suitable ethics resource and protect the information of those involved. ICF has its own code; the Global Code of Ethics is a separate framework supported by EMCC and other signatories.']
])}${source(A.ethics)}${article('reflectie','Cum înveți dintr-o conversație','How to learn from a conversation',[
['„A mers bine” este o impresie. Pentru a învăța, caută o secvență concretă: ce a spus clientul, ce ai făcut tu și ce ai observat după. Descrie fără să transformi observația în evaluarea persoanei.','“It went well” is an impression. To learn, find a concrete sequence: what the client said, what you did and what you noticed afterwards. Describe it without turning the observation into a judgment of the person.'],
['Separă trei straturi: ceea ce ai auzit, sensul pe care l-ai atribuit și intervenția aleasă. De exemplu, o pauză este observabilă; „s-a blocat” este interpretarea ta. Această diferență poate schimba următoarea întrebare.','Separate three layers: what you heard, the meaning you assigned and the intervention you chose. A pause is observable; “they got stuck” is your interpretation. This distinction can change the next question.'],
['Alege un singur lucru de exersat. Poate fi verificarea acordului sau scurtarea întrebărilor. Într-o practică cu acordul partenerului, cere feedback despre acel comportament, nu despre cât de bun coach pari.','Choose one thing to practise. It may be checking the agreement or shortening questions. In practice with your partner’s agreement, ask for feedback about that behaviour, not how good a coach you seem.'],
['Mentor coachingul și supervizarea pot susține dezvoltarea în moduri diferite. Verifică definițiile și cerințele organizației tale. Un jurnal personal ajută reflecția, dar nu înlocuiește feedbackul, formarea sau evaluarea profesională.','Mentor coaching and supervision can support development in different ways. Check your organisation’s definitions and requirements. A personal journal supports reflection but does not replace feedback, training or professional assessment.']
])}${link('invata.html','Încearcă în atelier','Try it in the studio','ac-btn ac-btn-primary')}</div>`);

page('individual.html','individual',pair('Coaching individual, pas cu pas','Individual coaching, step by step'),`${head('APLICAȚII / INDIVIDUAL','Un om. Contextul lui. Alegerile lui.','One person. Their context. Their choices.','De la prima întâlnire la încheiere: un cadru flexibil pentru coachingul individual.','From the first meeting to closing: a flexible framework for individual coaching.')}<div class="wrap ac-reading ac-prose"><img class="ac-article-image" src="assets/img/hero-individual.webp?v=3.0.0" width="1536" height="1024" alt="Ilustrație despre conversația de coaching individual" loading="lazy">${article('prima','Prima întâlnire, înainte de prima întrebare','The first meeting, before the first question',[
['Întâlnirea inițială este și o conversație despre potrivire. Clientul poate întreba despre experiență, pregătire și felul de lucru. Coachul explorează ce caută persoana și dacă acel sprijin se află în limitele competenței sale.','The initial meeting is also a conversation about fit. The client can ask about experience, training and working style. The coach explores what the person seeks and whether that support is within their competence.'],
['Clarificați rolurile, scopul, durata orientativă și modul de revizuire. Discutați confidențialitatea, excepțiile aplicabile, utilizarea eventualelor înregistrări și posibilitatea de a opri colaborarea. Acordul trebuie să fie înțeles, nu doar acceptat formal.','Clarify roles, purpose, indicative duration and review arrangements. Discuss confidentiality, applicable exceptions, any recordings and the possibility of ending the engagement. The agreement needs to be understood, not merely formally accepted.'],
['Nu este necesar să promiți un rezultat. Poți explica procesul și cum veți observa împreună utilitatea. Clientul are nevoie de suficientă informație ca să decidă, inclusiv timp să se gândească.','You do not need to promise an outcome. Explain the process and how you will observe its usefulness together. The client needs enough information to decide, including time to think.'],
['La final, întreabă ce a rămas neclar. Dacă nevoia cere altă specializare, discutați deschis limitele și opțiunile. O emoție sau un subiect personal nu impune automat oprirea coachingului; contează nevoia, riscul, competența și cadrul convenit.','At the end, ask what remains unclear. If the need calls for another specialism, openly discuss boundaries and options. An emotion or personal topic does not automatically require coaching to stop; needs, risk, competence and the agreement matter.']
])}${article('leadership','Când tema este leadershipul','When the topic is leadership',[
['Un lider poate explora modul în care ia decizii, deleagă sau gestionează relații. Dacă organizația finanțează programul, obiectivele și raportarea trebuie convenite cu persoanele relevante. Nu presupune că agenda sponsorului este automat agenda clientului.','A leader may explore decision-making, delegation or relationships. If the organisation funds the programme, goals and reporting should be agreed with the relevant people. Do not assume the sponsor’s agenda is automatically the client’s.'],
['Exemplu fictiv: Mihai vrea să fie mai clar în ședințe. În loc să îi prescrii un stil, explorezi ce înseamnă claritate pentru el, ce observă echipa și ce ar vrea să testeze. Un experiment poate fi să formuleze scopul întâlnirii și să invite întrebări.','Fictional example: Mihai wants to be clearer in meetings. Rather than prescribing a style, explore what clarity means to him, what the team notices and what he wants to test. One experiment may be stating the meeting’s purpose and inviting questions.']
])}${article('revizuire','Revizuiește, apoi încheie conștient','Review, then close deliberately',[
['Verificați periodic ce este util, ce nu mai este relevant și ce ar trebui schimbat. Clientul poate reformula obiectivele sau poate alege să încheie. Relația nu are nevoie să continue doar fiindcă a început.','Regularly check what is useful, what is no longer relevant and what should change. The client may revise goals or choose to end. The relationship does not need to continue simply because it began.'],
['La încheiere, explorați învățarea, resursele pe care persoana le recunoaște și felul în care vrea să continue independent. Dacă este nevoie de alt sprijin, discutați opțiunile fără presiune sau promisiuni.','At closing, explore learning, resources the person recognises and how they want to continue independently. If other support is needed, discuss options without pressure or promises.']
])}${source(A.core)} ${link('povesti.html#cariera','Intră în povestea Anei','Enter Ana’s story','ac-btn')}</div>`);

page('echipa.html','team',pair('Coachingul de echipă','Team coaching'),`${head('APLICAȚII / ECHIPE','Nu doar oameni în aceeași cameră.','More than people in the same room.','Coachingul de echipă privește scopul comun, relațiile și felul în care echipa învață împreună.','Team coaching explores shared purpose, relationships and how the team learns together.')}<div class="wrap ac-reading ac-prose"><img class="ac-article-image" src="assets/img/hero-echipa.webp?v=3.0.0" width="1536" height="1024" loading="lazy" alt="Ilustrație despre colaborarea într-o echipă">${article('sponsor','Cine este clientul când plătește organizația?','Who is the client when the organisation pays?',[
['Sponsorul poate finanța intervenția, liderul poate dori un rezultat, iar membrii echipei pot vedea problema altfel. Aceste perspective merită puse în conversație înainte să înceapă munca. Coachul nu devine agentul ascuns al unei singure părți.','The sponsor may fund the work, the leader may seek an outcome and team members may see the problem differently. Bring these perspectives into conversation before starting. The coach does not become the hidden agent of one party.'],
['Clarificați cine face parte din echipă, ce scop comun există și cum va fi observată utilitatea. Stabiliți ce rămâne în spațiul de lucru și ce poate fi raportat. Un acord individual nu este suficient pentru toate informațiile care circulă într-un grup.','Clarify who belongs to the team, the shared purpose and how usefulness will be observed. Agree what stays in the working space and what may be reported. An individual agreement does not cover all information circulating in a group.'],
['Coachul lucrează cu felul în care echipa interacționează: cine vorbește, cum se iau deciziile, ce presupuneri se repetă. Observațiile sunt oferite pentru explorare, nu ca diagnostice despre membri.','The coach works with how the team interacts: who speaks, how decisions are made and which assumptions repeat. Offer observations for exploration, not as diagnoses of members.'],
['Un pas ales împreună poate fi un experiment de echipă: o rundă de perspective înainte de decizie, apoi o revizuire a efectului. Nu orice întâlnire facilitată este coaching de echipă; rolul, scopul și competența trebuie clarificate.','A jointly chosen step may be a team experiment: a round of perspectives before a decision, followed by a review of its effect. Not every facilitated meeting is team coaching; role, purpose and competence need clarification.']
])}${article('siguranta','Siguranța de a contribui','Safety to contribute',[
['Faptul că liderul spune „puteți vorbi liber” nu înseamnă că toți trăiesc această libertate. Explorează împreună cu echipa ce condiții fac participarea posibilă și ce consecințe percep oamenii când exprimă un dezacord.','A leader saying “speak freely” does not mean everyone experiences that freedom. Explore with the team what conditions make participation possible and what consequences people anticipate when disagreeing.'],
['Evită să forțezi divulgarea sau să promiți că o conversație va rezolva orice conflict. Unele situații au nevoie de alte procese: management, mediere, investigație sau sprijin de specialitate. Coachingul trebuie contractat într-un rol potrivit.','Avoid forcing disclosure or promising that a conversation will resolve every conflict. Some situations need other processes: management, mediation, investigation or specialist support. Coaching needs an appropriate agreed role.']
])}${article('competente-echipa','Competențe de bază și formare specifică','Core competencies and specific training',[
['Cele opt competențe ICF rămân repere: etică, mentalitate, acorduri, încredere, prezență, ascultare, conștientizare și creștere. Contextul colectiv aduce complexitate suplimentară și cere pregătire specifică.','The eight ICF competencies remain reference points: ethics, mindset, agreements, trust, presence, listening, awareness and growth. The collective context adds complexity and calls for specific preparation.'],
['ICF ACTC și EMCC ITCA aparțin unor sisteme diferite. Nu sunt titluri interschimbabile și nu trebuie confundate cu acreditarea unui program de formare. Consultă organizația emitentă pentru cerințele actuale.','ICF ACTC and EMCC ITCA belong to different systems. They are not interchangeable titles and should not be confused with training programme accreditation. Consult the issuing organisation for current requirements.']
])}${link('competente.html','Explorează toate cele 8 competențe','Explore all 8 competencies','ac-btn')}${source('https://coachingfederation.org/credentialing/icf-specializations-overview/actc/','ICF: verifică specializarea de echipă','ICF: check the team specialisation')}${source('https://emccglobal.org/','EMCC: verifică ITCA','EMCC: check ITCA')}</div>`);

page('certificari.html','certificari',pair('Certificare, cu sens','Credentials, with clarity'),`${head('04 / CERTIFICARE','Un titlu e un reper. Practica îl susține.','A title is a reference point. Practice supports it.','Înțelege diferența dintre formare, certificatul școlii și acreditarea individuală. Apoi alege un traseu potrivit.','Understand the difference between training, a school certificate and an individual credential. Then choose a suitable path.')}<div class="wrap ac-reading">${section('systems','Trei lucruri diferite, frecvent confundate.','Three different things, often confused.',`<ol class="ac-steps"><li>${t('Formarea','Training','h3')}${t('Procesul în care înveți și practici. Verifică programa, observarea practicii și feedbackul.','The process in which you learn and practise. Check the curriculum, observed practice and feedback.','p')}</li><li>${t('Certificatul programului','Programme certificate','h3')}${t('Confirmă parcurgerea cerințelor unui program. Acreditarea școlii nu îți acordă automat o credențială individuală.','Confirms completion of a programme’s requirements. A school’s accreditation does not automatically grant you an individual credential.','p')}</li><li>${t('Credențiala individuală','Individual credential','h3')}${t('Este acordată de organismul profesional după îndeplinirea cerințelor sale de educație, experiență și evaluare.','Awarded by the professional body after meeting its education, experience and assessment requirements.','p')}</li></ol>`)}${section('credentials','ICF: ACC, PCC și MCC.','ICF: ACC, PCC and MCC.',`<div class="ac-grid ac-grid-3">${[['ACC','60+','100+'],['PCC','125+','500+'],['MCC','200+','2.500+']].map(([n,edu,exp])=>`<article class="ac-card ac-credential"><span class="ac-eyebrow">ICF</span><h3>${n}</h3><dl><dt>${t('Ore de educație','Education hours')}</dt><dd>${edu}</dd><dt>${t('Ore de experiență','Experience hours')}</dt><dd>${exp}</dd></dl></article>`).join('')}</div>${note('Repere de orientare, nu lista completă de eligibilitate. Mentor coachingul, evaluarea, examenul, distribuția orelor și ruta de aplicare au condiții specifice. Pentru MCC există și cerința de a deține sau a fi deținut PCC.','Orientation points, not a complete eligibility checklist. Mentor coaching, assessment, exams, hour distribution and application paths have specific conditions. MCC also requires holding or having held PCC.')}${source('https://coachingfederation.org/credentialing/icf-credentials-overview/','Vezi cerințele actuale direct la ICF','Check current requirements directly with ICF')}`)}${section('alternative','EMCC și cadrul național.','EMCC and the national framework.',`<div class="ac-grid ac-grid-2"><article class="ac-card"><h3>EMCC</h3>${t('Un sistem distinct de acreditare profesională, cu accent pe competență, practică reflexivă și dezvoltare. Verifică EIA pentru practician și EQA pentru programe; nu presupune echivalare automată cu ICF.','A distinct professional accreditation system, focused on competence, reflective practice and development. Check EIA for practitioners and EQA for programmes; do not assume automatic equivalence with ICF.','p')}${source('https://emccglobal.org/')}</article><article class="ac-card">${t('România / cadrul național','Romania / national framework','h3')}${t('Verifică exact denumirea calificării, furnizorul, autorizarea programului și tipul certificatului. Recunoașterea națională și acreditarea internațională sunt lucruri diferite. Un certificat nu rezolvă singur toate condițiile de exercitare a activității.','Verify the exact qualification, provider, programme authorisation and certificate type. National recognition and international accreditation are different. A certificate alone does not settle every condition for professional practice.','p')}${source('https://www.anc.edu.ro/')}</article></div>`)}${section('paths','Înainte să alegi o școală.','Before choosing a school.',`<div class="ac-checklist"><label><input type="checkbox">${t('Am verificat programul exact în directorul organismului care îl acreditează.','I checked the exact programme in the accrediting body’s directory.')}</label><label><input type="checkbox">${t('Știu ce certificat primesc și ce etape rămân pentru credențiala individuală.','I know which certificate I receive and what remains for the individual credential.')}</label><label><input type="checkbox">${t('Știu câtă practică observată și ce fel de feedback include.','I know how much observed practice and what feedback is included.')}</label><label><input type="checkbox">${t('Am discutat cu furnizorul despre format, prezență, mentorat și evaluare.','I discussed format, attendance, mentoring and assessment with the provider.')}</label></div>${note('Listă de orientare pentru această vizită; bifele nu se salvează.','Orientation checklist for this visit; checkmarks are not saved.')}<div class="ac-actions">${link('scoli.html','Explorează școli și programe','Explore schools and programmes','ac-btn ac-btn-primary')}${link('traseul-meu.html','Clarifică următorul pas','Clarify your next step')}</div>`)}${section('transitions','Ai deja o formare?','Already trained?',`${t('Cere organizației profesionale sau furnizorului o evaluare a documentelor tale. Recunoașterea învățării anterioare depinde de program și de ruta aleasă; nu există conversie automată ANC → ICF sau ICF → EMCC.','Ask the professional body or provider to assess your documentation. Recognition of prior learning depends on the programme and chosen route; there is no automatic ANC → ICF or ICF → EMCC conversion.','p')}${source('https://coachingfederation.org/credentialing/icf-credentials-overview/')}`)}${note('Surse oficiale consultate: 16 septembrie 2026. Confirmă cerințele înainte să aplici.','Official sources consulted: September 16, 2026. Confirm requirements before applying.')}</div>`);

page('traseul-meu.html','traseul-meu',pair('Următorul tău pas','Your next step'),`${head('ORIENTARE','Începe de unde ești.','Start where you are.','Alege situația care seamănă cu a ta. Acesta este un ghid de orientare, nu o evaluare de eligibilitate.','Choose the situation that sounds like yours. This is an orientation guide, not an eligibility assessment.')}<div class="wrap ac-reading">${[
['Sunt curios și pornesc de la zero','I am curious and starting from scratch','Începe cu definiția, limitele și câteva conversații fictive. Vezi dacă practica te interesează înainte să alegi o formare.','Start with the definition, boundaries and a few fictional conversations. See whether the practice interests you before choosing training.','descopera.html'],
['Vreau o formare profesională','I want professional training','Compară programe concrete: acreditare, practică observată, feedback și cerințe de absolvire. Întreabă explicit ce mai ai de făcut pentru acreditarea individuală.','Compare specific programmes: accreditation, observed practice, feedback and completion requirements. Ask explicitly what remains for an individual credential.','scoli.html'],
['Am făcut deja un curs','I have already completed a course','Strânge programa, numărul de ore și dovezile evaluării. Verifică ruta potrivită direct cu organismul profesional; nu presupune echivalarea.','Gather the curriculum, hours and assessment evidence. Check the appropriate path directly with the professional body; do not assume equivalence.','certificari.html#transitions'],
['Practic și vreau să mă dezvolt','I practise and want to develop','Alege o competență, cere feedback și reflectează asupra unei secvențe concrete. Explorează mentor coachingul, supervizarea și învățarea continuă în sistemul tău.','Choose a competency, seek feedback and reflect on a concrete sequence. Explore mentor coaching, supervision and continuing learning within your system.','invata.html']
].map((r,i)=>`<details class="ac-path-choice ac-card"><summary><span class="ac-index">0${i+1}</span>${t(r[0],r[1],'h2')}</summary><div>${t(r[2],r[3],'p')}${link(r[4],'Vezi pasul recomandat','See the suggested next step','ac-btn')}</div></details>`).join('')}</div>`);

// Keep the existing guided course and school directory within the same visual system.
for (const file of ['hub.html','forum.html','incepe.html','scoli.html','legal.html','404.html']) {
  let html=fs.readFileSync(file,'utf8');
  html=html.replace(/<header class="site-header">[\s\S]*?<\/header>/,nav).replace(/<footer class="site-footer">[\s\S]*?<\/footer>/,footer);
  if(!html.includes('assets/css/academy.css'))html=html.replace('</head>','<link rel="stylesheet" href="assets/css/academy.css?v='+VERSION+'"></head>');
  if(!html.includes('assets/css/old-money.css'))html=html.replace('</head>','<link rel="stylesheet" href="assets/css/old-money.css?v='+VERSION+'"></head>');
  fs.writeFileSync(file,html);
}
for(const file of fs.readdirSync('.').filter(f=>f.endsWith('.html'))){
  let h=fs.readFileSync(file,'utf8')
    .replaceAll('Coaching Path', SITE_NAME)
    .replaceAll('Coaching Learning Path', SITE_NAME)
    .replaceAll('coaching-path.onrender.com', 'coachinghub.ro')
    .replaceAll('coaching<span>path.</span>', 'coaching<span>hub.ro</span>')
    .replaceAll('c<span>p</span>', 'c<span>h</span>')
    .replaceAll('?v=2.0.0', '?v='+VERSION)
    .replaceAll('?v=3.0.0', '?v='+VERSION)
    .replaceAll('?v=4.0.0', '?v='+VERSION)
    .replaceAll('?v=4.1.0', '?v='+VERSION)
    .replaceAll('?v=4.3.0', '?v='+VERSION)
    .replaceAll('?v=4.3.1', '?v='+VERSION);
  if(file==='certificari.html') h=h.replaceAll('16 septembrie 2026','22 septembrie 2026');
  h=h.replace(/<meta name="apple-mobile-web-app-capable"[^>]*>\s*/g,'')
    .replace(/<meta name="apple-mobile-web-app-title"[^>]*>\s*/g,'')
    .replace(/<meta name="apple-mobile-web-app-status-bar-style"[^>]*>\s*/g,'')
    .replace(/<meta name="mobile-web-app-capable"[^>]*>\s*/g,'')
    .replace(/<link rel="manifest"[^>]*>\s*/g,'')
    .replace(/<link rel="apple-touch-icon"[^>]*>\s*/g,'');
  if(!h.includes('format-detection')) h=h.replace('</head>','<meta name="format-detection" content="telephone=no"></head>');
  if(!/<meta name="theme-color"[^>]*media="\(prefers-color-scheme: light\)"/.test(h)) h=h.replace('</head>','<meta name="theme-color" content="#1f4c3e" media="(prefers-color-scheme: light)"><meta name="theme-color" content="#14261f" media="(prefers-color-scheme: dark)"></head>');
  if(!h.includes('assets/css/old-money.css')) h=h.replace('</head>','<link rel="stylesheet" href="assets/css/old-money.css?v='+VERSION+'"></head>');
  h=h.replaceAll('content="#4b57d4"','content="#1f4c3e"')
    .replaceAll('content="#0a0e18"','content="#14261f"')
    .replaceAll('content="#173f35"','content="#1f4c3e"')
    .replaceAll('content="#f7f5ed"','content="#f3eee4"')
    .replaceAll('content="#0f1814"','content="#14261f"');
  h=h.replace(/<meta name="viewport" content="([^"]*)">/,(_,content)=>`<meta name="viewport" content="${content.includes('viewport-fit=')?content:content+', viewport-fit=cover'}">`);
  if(!h.includes('twitter:card')) h=h.replace('</head>','<meta name="twitter:card" content="summary_large_image"></head>');
  if(!h.includes('og:title')) {
    const title = (h.match(/<title>([^<]*)<\/title>/i) || [,'coachinghub.ro'])[1]
      .replace(/&/g,'&amp;').replace(/"/g,'&quot;');
    h=h.replace('</head>','<meta property="og:title" content="'+title+'"><meta property="og:type" content="website"></head>');
  }
  h=h.replaceAll('assets/fonts/inter-latin-ext-wght-normal.woff2"','assets/fonts/inter-latin-ext-wght-normal.woff2?v='+VERSION+'"');
  h=h.replaceAll('assets/fonts/inter-latin-wght-normal.woff2"','assets/fonts/inter-latin-wght-normal.woff2?v='+VERSION+'"');
  h=h.replace(/<input\b[^>]*type="search"[^>]*>/g,(tag)=>tag.includes('enterkeyhint=')?tag:tag.replace('type="search"','type="search" enterkeyhint="search"'));
  fs.writeFileSync(file,h);
}
